"""Gate G3 — deformation + runtime reports from the measured JSON (no hand-typed numbers).

Usage (from LifeQuest_Fox_V2/):  python 08_VALIDATION/scripts/make_reports_g3.py
Writes  08_VALIDATION/deformation_report_g3.md, 08_VALIDATION/gate_g3_runtime_report.md
"""
import json, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
P = lambda *p: os.path.join(ROOT, *p)
J = lambda *p: json.load(open(P(*p)))
ENV = J('08_VALIDATION', 'runtime_g3', 'deformation_envelope_g3.json')
M = J('04_ANIMATIONS', 'g3_challenge_social', 'anim_metrics_g3.json')['clips']
SPEC = J('04_ANIMATIONS', 'g3_challenge_social', 'anim_spec_g3.json')
FID = J('08_VALIDATION', 'runtime_g3', 'gltf_pose_fidelity_g3.json')

n = len(ENV['clips'])
L = ['# Gate G3 — deformation report', '',
     'Generated by `make_reports_g3.py` from `anim_metrics_g3.json` (anim_check_g2_1.py run on the G3 blend, runtime cage) and',
     '`deformation_envelope_g3.json` (qa_envelope_g3.py). Thresholds are the APPROVED ones, unchanged: per-metric maximum over every approved',
     'E2 + G1 + G1.1 clip (mirrored L/R) plus the hard rules of G1.1 / G2 / G2.1. **The G2.1 hidden-leg exceptions are not part of the',
     'envelope**: every G3 clip has to pass the RAW rule on its own (the resolver adds the RAW leg stretch, hidden ring included, as a limit).', '',
     '## Summary', '', '| | G3 |', '|---|---|',
     f"| clips passing the RAW check (unchanged rule, no exception) | **{sum(c['raw_pass'] for c in ENV['clips'].values())}/{n}** |",
     f"| clips passing the VISIBLE check (G2.1 diagnostic: stretch on visible edges only) | **{sum(c['visible_pass'] for c in ENV['clips'].values())}/{n}** |",
     f"| hard-rule failures (start / end pose, foot slide, ground, scarf / tail in body) | **{sum(sum(not v for v in c['hard_rules'].values()) for c in ENV['clips'].values())}** |",
     f"| hidden-edge exceptions used | **0** |", '',
     '## Per clip (worst value over the clip)', '',
     '| Clip | RAW / VISIBLE | paw-in-head mm | scarf-in-head mm (count) | scarf-in-body | arm stretch L / R | body stretch | leg stretch RAW (visible) | ear stretch L / R | foot slide mm/f | start / end pose (deg / mm) | failures |',
     '|---|---|---|---|---|---|---|---|---|---|---|---|']
for name, c in M.items():
    e = ENV['clips'][name]; v = lambda k: c['stretch_p99_max'].get(k)
    leg = f"{max(v('FOX_Leg_L') or 0, v('FOX_Leg_R') or 0)} ({max(c.get('vis_stretch_p99_max', {}).get('FOX_Leg_L', 0), c.get('vis_stretch_p99_max', {}).get('FOX_Leg_R', 0))})"
    rm = c.get('rest_match', {}); pose = max(rm.get('start_deg/mm', [0]) + rm.get('end_deg/mm', [0])) if rm else '—'
    fails = [f"{f['metric']} {f['g3']}>{f['approved_max']}" for f in e['raw_failures']] + [h for h, ok in e['hard_rules'].items() if not ok]
    L.append(f"| {name} | {'✔' if e['raw_pass'] else '✘'} / {'✔' if e['visible_pass'] else '✘'} | {c.get('arm_in_head_max_depth_mm', 0)} | {c.get('scarf_in_head_max_depth_mm', 0)} ({c['scarf_new_in_head']}) | {c['scarf_new_in_body']} "
             f"| {v('FOX_Arm_L')} / {v('FOX_Arm_R')} | {v('FOX_Body')} | {leg} | {v('FOX_Ear_L')} / {v('FOX_Ear_R')} | {(c.get('foot_slide_mm_per_frame') or {}).get('max')} | {pose} | {'; '.join(fails) or '—'} |")
env = ENV['raw_envelope']
L += ['', 'Approved limits (E2 + G1 + G1.1): ' + ', '.join(f'{k} {v}' for k, v in sorted(env.items()) if 'stretch' in k or 'depth' in k or 'new_in' in k) + '; foot slide 0.05 mm/frame on standing frames; start / end pose ≤ 0.01.', '',
      '## Resolver (`anim_g3.py`, imported G2.1 pipeline)', '',
      'Frames over a resolver limit before / after and the smallest factor applied per channel group (1 = untouched; never below 0.6 — at least 60 % of every gesture is kept):', '',
      '| Clip | violating frames | min factor per group | unresolved |', '|---|---|---|---|']
for k, r in SPEC['resolver'].items():
    L.append(f"| {k} | {r['violating_frames_before']} → {r['violating_frames_after']} | {r['min_factor'] or '—'} | {r['unresolved'] or '—'} |")
L += ['', '## Ground contact', '', '| Clip | frames re-grounded | max |dz| m |', '|---|---|---|'] + [f"| {k} | {v['frames_corrected']} | {v['max_abs_dz_m']} |" for k, v in SPEC['ground_contact'].items()]
L += ['', '## Duo contact geometry', '',
      'The paw reaches ~0.30 m from the fox axis while the head is ~0.34 m wide (measured with `g3_probe.py` on the runtime cage): two upright foxes',
      'cannot touch paws without their heads intersecting. duo_celebrate therefore makes the contact in the air: both foxes hop 0.12 m toward each',
      'other, their bodies arc 12° outward (head edge −0.14 m) and the low reaching paw meets the partner\'s at the apex (f36); they rebound to their',
      'start spots before landing, so no foot moves while on the floor. Contact points (paw tips, fx-root local, measured): ' +
      ', '.join(f"{k} {v['pos']}" for k, v in SPEC['prop_anchors'].items() if k.endswith('_head')) + f"; airborne window f{SPEC['clips']['duo_celebrate']['contact'].get('airborne_frames')}.", '',
      '## glTF pose fidelity', '', f"G3 module vs Blender worst **{FID['g3_module_vs_blender']['worst']['max_mm']} mm** at {FID['g3_module_vs_blender']['worst']['at']} (tolerance 6.0 mm, as G1.1 / G2.1; approved E2 GLB {FID['e2_approved_glb_vs_blender']['worst']['max_mm']} mm)."]
open(P('08_VALIDATION', 'deformation_report_g3.md'), 'w').write('\n'.join(L) + '\n')

RT = J('08_VALIDATION', 'runtime_g3', 'g3_runtime_report.json')
REGF = P('08_VALIDATION', 'runtime_g3', 'regressions_g3.json')
REG = json.load(open(REGF)) if os.path.exists(REGF) else {}
R = ['# Gate G3 — runtime validation & regression report', '', 'Generated by `make_reports_g3.py`. Headless Chrome with a CPU rasteriser (SwiftShader): draw calls and object counts are counted; no GPU timing is claimed.', '',
     f"## G3 browser suite (`browser_g3_test.py`, sandbox `companion_sandbox_g3`): **{RT['summary']}**", '', '| Check | Result |', '|---|---|'] + [f"| {c['name']} | {'PASS' if c['pass'] else '**FAIL**'} |" for c in RT['checks']]
mt = {t['name']: t for t in RT['measurements'].get('multi_tests', [])}
R += ['', '## Duo / group measurements', '']
for name, t in mt.items():
    d = t['detail']; rep = d.get('report', {})
    R.append(f"* **{name}** — {'PASS' if t['pass'] else 'FAIL'}: " + json.dumps({k: rep.get(k) for k in ('mode', 'startTicks', 'maxClipTimeDeltaS', 'contact', 'heightCompensationMm', 'sharedContact', 'sharedBursts') if k in rep} | {k: d[k] for k in ('minHeadGapMm', 'minPawMm', 'bIdle', 'aPlaying', 'suppressed') if k in d}, ensure_ascii=False))
rc = RT['measurements'].get('render_counts', {})
R += ['', '## Render counts (one canvas, software renderer)', '', '| Stage | draw calls | triangles | geometries | textures | JS heap MB |', '|---|---|---|---|---|---|'] + [f"| {k} | {v['calls']} | {v['triangles']} | {v['geometries']} | {v['textures']} | {v['jsHeapMB']} |" for k, v in rc.items()]
if REG:
    R += ['', '## Regressions of the approved suites against the G3 runtime (`regress_g3.py`, assertions unchanged)', '', '| Suite | Script | Build / URL | Result |', '|---|---|---|---|']
    for k, v in REG.items():
        res = v['summary'][-1] if v['summary'] else f"exit {v['exit']}"
        if k == 'e2':
            e2 = J('08_VALIDATION', 'runtime_g3', 'regress_e2', 'anim_runtime_report_e2.json'); t = e2['page_checks'] + e2['interaction_tests']; res = f"{sum(x['status'] == 'PASS' for x in t)}/{len(t)} PASS"
        if k == 'flame_g1_1':
            fl = J('08_VALIDATION', 'runtime_g3', 'regress_flame_g1_1', 'flame_attachment_g1_1.json'); res = f"exit {v['exit']} · max attach err Lv1 {fl['lv1']['max_attach_err_mm']} mm, Lv30 {fl['lv30']['max_attach_err_mm']} mm"
        R.append(f"| {k} | `{v['script']} {' '.join(a for a in v['args'] if not a.startswith('/'))}` | {v['url']} | {res}{' — FAILS: ' + '; '.join(v['fails'])[:300] if v['fails'] else ''} |")
open(P('08_VALIDATION', 'gate_g3_runtime_report.md'), 'w').write('\n'.join(R) + '\n')
print('ok', RT['summary'])
